// Bundled default Apple Wallet pass art, one set per redeem template. The
// DEFAULT_ASSETS_B64 table is GENERATED by scripts/render-pass-art.mjs (base64
// of models/themes/<template>/*.png, drawn for the colours in passThemes.ts) —
// re-run the script instead of editing it. These guarantee a merchant with no
// uploaded branding still issues a VALID, on-brand pass (Apple requires
// icon.png). Decoded to Buffers at runtime so there is NO disk read (Vercel
// file-tracing safe) — do NOT read models/ at runtime.
import { templateKey, type TemplateKey } from "./config";
import type { WalletAsset } from "./wallet/apple/assets";

const DEFAULT_ASSETS_B64: Record<TemplateKey, Record<WalletAsset, string>> = {
  cafe: {
    "icon.png": "",
    "icon@2x.png": "",
    "icon@3x.png": "",
    "logo.png": "",
    "logo@2x.png": "",
    "logo@3x.png": "",
    "strip.png": "",
    "strip@2x.png": "",
    "strip@3x.png": "",
  },
  restaurant: {
    "icon.png": "",
    "icon@2x.png": "",
    "icon@3x.png": "",
    "logo.png": "",
    "logo@2x.png": "",
    "logo@3x.png": "",
    "strip.png": "",
    "strip@2x.png": "",
    "strip@3x.png": "",
  },
  retail: {
    "icon.png": "",
    "icon@2x.png": "",
    "icon@3x.png": "",
    "logo.png": "",
    "logo@2x.png": "",
    "logo@3x.png": "",
    "strip.png": "",
    "strip@2x.png": "",
    "strip@3x.png": "",
  },
};

const cache = new Map<string, Buffer>();

/** Bundled default art for a pass asset filename in a template's set, or undefined if none. */
export function defaultAssetBuffer(name: string, template: unknown): Buffer | undefined {
  const key = templateKey(template);
  const b64 = (DEFAULT_ASSETS_B64[key] as Record<string, string>)[name];
  if (!b64) return undefined;
  const id = `${key}/${name}`;
  let buf = cache.get(id);
  if (!buf) {
    buf = Buffer.from(b64, "base64");
    cache.set(id, buf);
  }
  return buf;
}

/** Filenames that have a bundled default (every template bundles the same set). */
export const DEFAULT_ASSET_NAMES = Object.keys(DEFAULT_ASSETS_B64.restaurant);

/**
 * A merchant's uploaded pass art plus their template's bundled defaults. A
 * default fills a missing file only when the merchant has not uploaded that
 * image's base file, so their own logo.png + logo@2x.png is never mixed with a
 * default logo@3x.png on 3x iPhones (Wallet scales their @2x instead).
 * icon.png is its own base, so it is always present.
 */
export function withDefaultArt(uploaded: Record<string, Buffer>, template: unknown): Record<string, Buffer> {
  const out = { ...uploaded };
  for (const name of DEFAULT_ASSET_NAMES) {
    const base = name.replace(/@\dx\.png$/, ".png");
    if (uploaded[name] || uploaded[base]) continue;
    out[name] = defaultAssetBuffer(name, template)!;
  }
  return out;
}
